/// <summary>
/// PB-355: Metcash Parameters FastTab on Form notes (FormLetterRemarks).
/// </summary>
public final class METFormLetterRemarksEventHandler
{
}

Method.Source:
[FormEventHandler(formStr(FormLetterRemarks), FormEventType::Initialized)]
public static void FormLetterRemarks_OnInitialized(xFormRun _sender, FormEventArgs _e)
{
    METFormLetterRemarksEventHandler::showParameters(_sender, false);
}

[FormDataSourceEventHandler(formDataSourceStr(FormLetterRemarks, FormLetterRemarks), FormDataSourceEventType::Activated)]
public static void FormLetterRemarks_OnActivated(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    METFormLetterRemarksEventHandler::refreshVisibility(_sender);
}

[FormDataFieldEventHandler(formDataFieldStr(FormLetterRemarks, FormLetterRemarks, FormLetter), FormDataFieldEventType::Modified)]
public static void FormLetterRemarks_FormLetter_OnModified(FormDataObject _sender, FormDataFieldEventArgs _e)
{
    METFormLetterRemarksEventHandler::refreshVisibility(_sender.datasource());
}

[FormDataSourceEventHandler(formDataSourceStr(FormLetterRemarks, METCustStmtSetupInvoice), FormDataSourceEventType::Initialized)]
public static void METCustStmtSetupInvoice_OnInitialized(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    METFormLetterRemarksEventHandler::lockTransTypeRange(_sender, METCustStmtTransType::SalesInvoice);
}

[FormDataSourceEventHandler(formDataSourceStr(FormLetterRemarks, METCustStmtSetupInvoice), FormDataSourceEventType::Created)]
public static void METCustStmtSetupInvoice_OnCreated(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    METCustStmtDescriptionSetup setup = _sender.cursor();

    setup.TransType = METCustStmtTransType::SalesInvoice;
}

[FormDataSourceEventHandler(formDataSourceStr(FormLetterRemarks, METCustStmtSetupCreditNote), FormDataSourceEventType::Initialized)]
public static void METCustStmtSetupCreditNote_OnInitialized(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    METFormLetterRemarksEventHandler::lockTransTypeRange(_sender, METCustStmtTransType::SalesCreditNote);
}

[FormDataSourceEventHandler(formDataSourceStr(FormLetterRemarks, METCustStmtSetupCreditNote), FormDataSourceEventType::Created)]
public static void METCustStmtSetupCreditNote_OnCreated(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    METCustStmtDescriptionSetup setup = _sender.cursor();

    setup.TransType = METCustStmtTransType::SalesCreditNote;
}

public static boolean isCustAccountStatement(FormTextType _formTextType)
{
    return _formTextType == FormTextType::CustACStatementExt;
}

private static void refreshVisibility(FormDataSource _formLetterRemarksDs)
{
    FormLetterRemarks formLetterRemarks = _formLetterRemarksDs.cursor();

    METFormLetterRemarksEventHandler::showParameters(
        _formLetterRemarksDs.formRun(),
        METFormLetterRemarksEventHandler::isCustAccountStatement(formLetterRemarks.FormLetter));
}

private static void showParameters(FormRun _formRun, boolean _show)
{
    FormControl parameters = _formRun.design().controlName(formControlStr(FormLetterRemarks, METCustStmtParameters));

    if (parameters)
    {
        parameters.visible(_show);
    }
}

private static void lockTransTypeRange(FormDataSource _setupDs, METCustStmtTransType _transType)
{
    QueryBuildRange range = SysQuery::findOrCreateRange(
        _setupDs.queryBuildDataSource(),
        fieldNum(METCustStmtDescriptionSetup, TransType));

    range.value(queryValue(_transType));
    range.status(RangeStatus::Hidden);
}

/// <summary>
/// PB-355: Industry key dropdown on the Sales invoice grid.
/// </summary>
[FormControlEventHandler(formControlStr(FormLetterRemarks, METCustStmtSalesInvoiceGrid_IndustryKey), FormControlEventType::Lookup)]
public static void METCustStmtSalesInvoiceGrid_IndustryKey_OnLookup(FormControl _sender, FormControlEventArgs _e)
{
    METFormLetterRemarksEventHandler::industryKeyLookup(_sender, _e);
}

/// <summary>
/// PB-355: Industry key dropdown on the Sales credit note grid.
/// </summary>
[FormControlEventHandler(formControlStr(FormLetterRemarks, METCustStmtSalesCreditNoteGrid_IndustryKey), FormControlEventType::Lookup)]
public static void METCustStmtSalesCreditNoteGrid_IndustryKey_OnLookup(FormControl _sender, FormControlEventArgs _e)
{
    METFormLetterRemarksEventHandler::industryKeyLookup(_sender, _e);
}

/// <summary>
/// Distinct, non-blank industry keys that exist in the system, sorted.
/// </summary>
private static void industryKeyLookup(FormControl _sender, FormControlEventArgs _e)
{
    Query                query = new Query();
    QueryBuildDataSource qbds  = query.addDataSource(tableNum(METSalesTable));

    qbds.addRange(fieldNum(METSalesTable, IndustryKey)).value(SysQuery::valueNotEmptyString());
    qbds.addGroupByField(fieldNum(METSalesTable, IndustryKey));
    qbds.addOrderByField(fieldNum(METSalesTable, IndustryKey));

    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(METSalesTable), _sender);
    sysTableLookup.addLookupfield(fieldNum(METSalesTable, IndustryKey), true);
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();

    FormControlCancelableSuperEventArgs cancelableArgs = _e as FormControlCancelableSuperEventArgs;
    cancelableArgs.CancelSuperCall();
}
